max_in_flight, held, dropped = 3, [], 0
for f in range(1, 8):
    if len(held) == max_in_flight:
        dropped += 1; print(f"프레임{f}: 빈 버퍼 없음 → 버림")
    else:
        held.append(f); print(f"프레임{f}: 앱에 전달 (들고 있는 수 {len(held)})")
    if f % 3 == 0 and held:
        print(f"  앱이 doneWithFrame({held.pop(0)})")
print("버린 프레임:", dropped)
# ... 프레임5: 빈 버퍼 없음 → 버림 / 프레임6: 빈 버퍼 없음 → 버림 ... 버린 프레임: 2
